spec.expr:
label_join(
     sum by (site, host_name, system_device) (
           system_filesystem_utilization_ratio{system_filesystem_state=~"used|reserved", system_filesystem_type !~"$filesystemFilter"}
     ),
     "id", ":", "host_name", "system_device"
)

label_join(
  (
    sum by (site, host_name, system_device) (
      system_filesystem_usage_bytes{system_filesystem_state="free"}
    )
    / ignoring(system_filesystem_state)
    sum by (site, host_name, system_device) (
      delta(system_filesystem_usage_bytes{system_filesystem_state="used"}[$__range]) / $__range_s
    )
  ) 
  and ignoring(system_filesystem_state)
  sum by (site, host_name, system_device) (
    delta(system_filesystem_usage_bytes{system_filesystem_state="used"}[$__range])
  ) > 0,
  "id", ":", "host_name", "system_device"
)

